	@Test
	void visibleSelectorResolvesAnActualNonNullPrivateAlias() {
		var vf = SimpleValueFactory.getInstance();
		Projection inner = new Projection(new SingletonSet(), new ProjectionElemList(), true);
		Projection outer = new Projection(inner, new ProjectionElemList(), true);
		Var outerSelector = Var.of("outer", vf.createIRI("urn:null-selector:outer"), true, true);
		outer.setProjectionContext(outerSelector);
		outer.setInheritedGraphParameter("_actualGraph");
		inner.setProjectionContext(Var.of("_actualGraph"));
		assertAll(
				() -> assertSame(outerSelector, inner.getVisibleProjectionContext()),
				() -> {
					outer.setInheritedGraphParameter(null);
					outer.setFixedGraphParameter("_actualGraph");
					assertSame(outerSelector, inner.getVisibleProjectionContext());
				});
	}

	@Test
	void sameNamedLocalAndInheritedContextsHaveDistinctMeaning() {
		Projection projection = projection();
		Var inherited = Var.of("g");
		int originalHash = inherited.hashCode();
		inherited.setGraphContextDepth(1);
		assertNotEquals(originalHash, inherited.hashCode());
		StatementPattern pattern = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				Var.of("x"), Var.of("p"), Var.of("o"), inherited);
		projection.setArg(pattern);
		assertTrue(projection.isInheritedGraphContext(pattern, inherited));
		Var local = Var.of("g");
		assertNotEquals(local, inherited);
		assertFalse(projection.isInheritedGraphContext(pattern, local));
	}

	@Test
	void privateContextRolesFollowExactChildrenAcrossCopiesAndCollections() throws Exception {
		for (TupleExpr producer : contextProducers()) {
			Var context = context(producer);
			TupleExpr ordinary = producer.clone();
			PrivateGraphContextRole.mark(producer, context);
			assertNotEquals(ordinary, producer);
			TupleExpr clone = producer.clone();
			assertEquals(producer, clone);
			assertEquals(producer.hashCode(), clone.hashCode());
			assertNotSame(context, context(clone));
			assertTrue(PrivateGraphContextRole.isPrivateContext(clone, context(clone)));
			TupleExpr restored = serializedCopy(producer);
			assertEquals(producer, restored);
			assertEquals(producer.hashCode(), restored.hashCode());
			assertTrue(PrivateGraphContextRole.isPrivateContext(restored, context(restored)));
			Set<TupleExpr> producers = new HashSet<>();
			producers.add(ordinary);
			producers.add(producer);
			producers.add(clone);
			producers.add(restored);
			assertEquals(2, producers.size());
			new QueryRoot(restored);
			assertTrue(PrivateGraphContextRole.isPrivateContext(restored, context(restored)));
			TupleExpr bnodeChanged = producer.clone();
			context(bnodeChanged).setBNode(true);
			assertFalse(PrivateGraphContextRole.isPrivateContext(bnodeChanged, context(bnodeChanged)));
			TupleExpr scopeFlagChanged = producer.clone();
			context(scopeFlagChanged).setVariableScopeChange(true);
			assertTrue(PrivateGraphContextRole.isPrivateContext(scopeFlagChanged, context(scopeFlagChanged)));
			assertEquals(producer, scopeFlagChanged);
			assertEquals(producer.hashCode(), scopeFlagChanged.hashCode());
			TupleExpr scopeFlagCopy = scopeFlagChanged.clone();
			assertTrue(PrivateGraphContextRole.isPrivateContext(scopeFlagCopy, context(scopeFlagCopy)));
			TupleExpr scopeFlagRestored = serializedCopy(scopeFlagChanged);
			assertTrue(context(scopeFlagRestored).isVariableScopeChange());
			assertTrue(PrivateGraphContextRole.isPrivateContext(scopeFlagRestored, context(scopeFlagRestored)));
			assertEquals(scopeFlagChanged, scopeFlagRestored);
			TupleExpr ownerScopeChanged = producer.clone();
			((AbstractQueryModelNode) ownerScopeChanged).setVariableScopeChange(true);
			assertTrue(PrivateGraphContextRole.isPrivateContext(ownerScopeChanged, context(ownerScopeChanged)));
			assertEquals(producer, ownerScopeChanged);
			assertEquals(producer.hashCode(), ownerScopeChanged.hashCode());
			TupleExpr ownerScopeCopy = ownerScopeChanged.clone();
			assertTrue(PrivateGraphContextRole.isPrivateContext(ownerScopeCopy, context(ownerScopeCopy)));
			TupleExpr ownerScopeRestored = serializedCopy(ownerScopeChanged);
			assertTrue(((AbstractQueryModelNode) ownerScopeRestored).isVariableScopeChange());
			assertTrue(PrivateGraphContextRole.isPrivateContext(ownerScopeRestored, context(ownerScopeRestored)));
			assertEquals(ownerScopeChanged, ownerScopeRestored);
			if (producer instanceof ZeroLengthPath || producer instanceof ArbitraryLengthPath) {
				TupleExpr changedScope = producer.clone();
				if (changedScope instanceof ZeroLengthPath path) {
					path.setScope(StatementPattern.Scope.DEFAULT_CONTEXTS);
					path.setScope(StatementPattern.Scope.NAMED_CONTEXTS);
				} else {
					ArbitraryLengthPath path = (ArbitraryLengthPath) changedScope;
					path.setScope(StatementPattern.Scope.DEFAULT_CONTEXTS);
					path.setScope(StatementPattern.Scope.NAMED_CONTEXTS);
				}
				assertFalse(PrivateGraphContextRole.isPrivateContext(changedScope, context(changedScope)));
			}

			Var replacement = context(clone).clone();
			replaceContext(clone, replacement);
			assertFalse(PrivateGraphContextRole.isPrivateContext(clone, replacement));
			assertEquals(ordinary, clone);
			context.setGraphContextDepth(context.getGraphContextDepth() + 1);
			assertFalse(PrivateGraphContextRole.isPrivateContext(producer, context));
		}
	}

	@Test
	void genuineLocalContextReplacementCannotInheritThePriorRole() throws Exception {
		var localGraph = SimpleValueFactory.getInstance().createIRI("urn:role:local-graph");
		for (TupleExpr producer : contextProducers()) {
			PrivateGraphContextRole.mark(producer, context(producer));
			Var replacement = Var.of("localGraph", localGraph);
			replaceContext(producer, replacement);
			assertSame(replacement, context(producer));
			assertEquals(0, replacement.getGraphContextDepth());
			assertFalse(PrivateGraphContextRole.isPrivateContext(producer, replacement));
			TupleExpr restored = serializedCopy(producer);
			assertEquals(localGraph, context(restored).getValue());
			assertFalse(PrivateGraphContextRole.isPrivateContext(restored, context(restored)));
		}
	}

