	private static List<TupleExpr> contextProducers() {
		var graph = SimpleValueFactory.getInstance().createIRI("urn:role:graph");
		Var statementContext = Var.of("privateGraph", graph, true, false);
		Var zeroContext = statementContext.clone();
		Var arbitraryContext = statementContext.clone();
		statementContext.setGraphContextDepth(1);
		zeroContext.setGraphContextDepth(1);
		arbitraryContext.setGraphContextDepth(1);
		StatementPattern statement = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				Var.of("s"), Var.of("p"), Var.of("o"), statementContext);
		ZeroLengthPath zero = new ZeroLengthPath(StatementPattern.Scope.NAMED_CONTEXTS,
				Var.of("s"), Var.of("o"), zeroContext);
		StatementPattern edge = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));
		ArbitraryLengthPath arbitrary = new ArbitraryLengthPath(StatementPattern.Scope.NAMED_CONTEXTS,
				Var.of("s"), edge, Var.of("o"), arbitraryContext, 1);
		return List.of(statement, zero, arbitrary);
	}

	private static Var context(TupleExpr producer) {
		if (producer instanceof StatementPattern pattern) {
			return pattern.getContextVar();
		}
		if (producer instanceof ZeroLengthPath path) {
			return path.getContextVar();
		}
		return ((ArbitraryLengthPath) producer).getContextVar();
	}

	private static void replaceContext(TupleExpr producer, Var replacement) {
		if (producer instanceof StatementPattern pattern) {
			pattern.replaceChildNode(pattern.getContextVar(), replacement);
		} else if (producer instanceof ZeroLengthPath path) {
			path.setContextVar(replacement);
		} else {
			((ArbitraryLengthPath) producer).setContextVar(replacement);
		}
	}

	private static TupleExpr serializedCopy(TupleExpr producer) throws Exception {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
			output.writeObject(producer);
		}
		try (ObjectInputStream input = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			return (TupleExpr) input.readObject();
		}
	}

